252	     * digits contained in the {@code customerCode}. Returns {@code null} when the customerCode is
253	     * absent, so owners without a customerCode map cleanly.
254	     */
255	    default Integer checkDigit(Owner owner) {
256	        String customerCode = owner.getCustomerCode();
257	        if (customerCode == null) {
258	            return null;
259	        }
260	        int sum = 0;
261	        boolean dbl = true;
262	        for (int i = customerCode.length() - 1; i >= 0; i--) {
263	            char c = customerCode.charAt(i);
264	            if (c < '0' || c > '9') {
265	                continue;
266	            }
267	            int d = c - '0';
268	            if (dbl) {
269	                d *= 2;
270	                if (d > 9) {
271	                    d -= 9;
272	                }
273	            }
274	            sum += d;
275	            dbl = !dbl;
276	        }
277	        return (10 - (sum % 10)) % 10;
278	    }
279	
280	    Owner toOwner(OwnerDto ownerDto);
281	
282	    @Mapping(target = "id", ignore = true)
283	    @Mapping(target = "pets", ignore = true)
284	    @Mapping(target = "customerCode", ignore = true)
285	    @Mapping(target = "householdId", ignore = true)
286	    @Mapping(target = "namesakeCount", ignore = true)
287	    @Mapping(target = "householdMemberCount", ignore = true)
288	    @Mapping(target = "possibleDuplicate", ignore = true)
289	    @Mapping(target = "possibleDuplicateOf", ignore = true)
