297	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
298	        OwnerPageDto ownerPageDto = new OwnerPageDto();
299	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
300	        ownerPageDto.setPage(ownerPage.getNumber());
301	        ownerPageDto.setSize(ownerPage.getSize());
302	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
303	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
304	        return ownerPageDto;
305	    }
306	}
